<?php
require "db.php";
$id=(int)($_GET['id']??0);
$stmt=$conn->prepare("SELECT pay.payment_id,pay.payment_date,pay.amount,pay.method,b.booking_id,b.seat_number,b.travel_class,b.passenger_count,p.passenger_id,p.name passenger_name,p.email,p.phone,f.flight_id,f.flight_name,f.route,f.departure_date,f.departure_time,f.boarding_time,f.gate_no,f.travel_time,a.airport_name FROM payments pay JOIN bookings b ON b.booking_id=pay.booking_id JOIN passengers p ON p.passenger_id=b.passenger_id JOIN flights f ON f.flight_id=b.flight_id LEFT JOIN airports a ON a.airport_id=b.airport_id WHERE pay.payment_id=?");
$stmt->bind_param("i",$id); $stmt->execute(); $pass=$stmt->get_result()->fetch_assoc();
$flightCode=$pass?'FL-'.str_pad($pass['flight_id'],5,'0',STR_PAD_LEFT):'';
$barcodeValue=$pass?$flightCode.'|FA-'.str_pad($pass['booking_id'],6,'0',STR_PAD_LEFT).'|'.strtoupper($pass['seat_number']).'|'.strtoupper($pass['travel_class']):'';
$code128Patterns=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312131','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
$barcodeRects=''; $barcodeWidth=420;
if($pass){$startCode=104;$checksum=$startCode;$codes=[$startCode];foreach(str_split($barcodeValue) as $i=>$ch){$v=ord($ch)-32;if($v<0||$v>95)$v=0;$codes[]=$v;$checksum+=$v*($i+1);}$codes[]=$checksum%103;$codes[]=106;$x=8;$scale=2.2;foreach($codes as $code){$pattern=$code128Patterns[$code];$draw=true;for($j=0;$j<strlen($pattern);$j++){$w=(int)$pattern[$j]*$scale;if($draw)$barcodeRects.='<rect x="'.round($x,2).'" y="0" width="'.round($w,2).'" height="72"/>';$x+=$w;$draw=!$draw;}}$barcodeWidth=ceil($x+8);}
?>
