<div class="pass-item"><small>Passenger</small><b><?=e($pass['passenger_name'])?></b></div><div class="pass-item"><small>Passenger ID</small><b>PA-<?=str_pad($pass['passenger_id'],5,'0',STR_PAD_LEFT)?></b></div><div class="pass-item"><small>Flight ID</small><b><?=e($flightCode)?></b></div><div class="pass-item"><small>Flight</small><b><?=e($pass['flight_name'])?></b></div><div class="pass-item"><small>Date</small><b><?=e(date('d M Y',strtotime($pass['departure_date'])))?></b></div><div class="pass-item"><small>Departure</small><b><?=e(date('h:i A',strtotime($pass['departure_time'])))?></b></div><div class="pass-item"><small>Boarding</small><b><?=e(date('h:i A',strtotime($pass['boarding_time'])))?></b></div><div class="pass-item"><small>Class</small><b><?=e($pass['travel_class'])?></b></div><div class="pass-item"><small>Seat</small><b><?=e($pass['seat_number'])?></b></div><div class="pass-item"><small>Gate</small><b><?=e($pass['gate_no'])?></b></div><div class="pass-item"><small>Travel Time</small><b><?=e($pass['travel_time']?:'—')?></b></div><div class="pass-item"><small>Airport</small><b><?=e($pass['airport_name']?:'—')?></b></div></div>
<div class="boarding-barcode"><svg viewBox="0 0 <?=$barcodeWidth?> 92" role="img" aria-label="Boarding pass barcode"><rect x="0" y="0" width="<?=$barcodeWidth?>" height="72" fill="white"/><?=$barcodeRects?><text x="<?=($barcodeWidth/2)?>" y="88" text-anchor="middle" font-size="10" font-family="monospace" fill="black"><?=e($barcodeValue)?></text></svg></div></div></div></div>
